Acá va una implementación con **solo `std`**, leyendo en streaming con `BufReader`. Soporta comillas (`"..."`) y comas dentro de campos entrecomillados. La columna es **0-based**. Devuelve `Ok(None)` si no encuentra valores numéricos.

```rust
use std::borrow::Cow;
use std::fs::File;
use std::io::{self, BufRead, BufReader};

struct CsvFields<'a> {
    line: &'a str,
    pos: usize,
    done: bool,
}

impl<'a> CsvFields<'a> {
    fn new(line: &'a str) -> Self {
        Self {
            line,
            pos: 0,
            done: false,
        }
    }
}

impl<'a> Iterator for CsvFields<'a> {
    type Item = io::Result<Cow<'a, str>>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.done {
            return None;
        }

        let bytes = self.line.as_bytes();
        let len = bytes.len();

        // Campo vacío final, p. ej. "a,b,"
        if self.pos == len {
            self.done = true;
            return Some(Ok(Cow::Borrowed("")));
        }

        // Campo entrecomillado
        if bytes[self.pos] == b'"' {
            self.pos += 1;
            let mut out = String::new();
            let mut segment_start = self.pos;

            loop {
                if self.pos >= len {
                    self.done = true;
                    return Some(Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "comilla sin cerrar",
                    )));
                }

                if bytes[self.pos] == b'"' {
                    out.push_str(&self.line[segment_start..self.pos]);

                    // Comilla escapada: ""
                    if self.pos + 1 < len && bytes[self.pos + 1] == b'"' {
                        out.push('"');
                        self.pos += 2;
                        segment_start = self.pos;
                    } else {
                        // Comilla de cierre
                        self.pos += 1;

                        if self.pos < len {
                            if bytes[self.pos] == b',' {
                                self.pos += 1;
                                return Some(Ok(Cow::Owned(out)));
                            } else {
                                self.done = true;
                                return Some(Err(io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "caracter después de comilla de cierre",
                                )));
                            }
                        } else {
                            self.done = true;
                            return Some(Ok(Cow::Owned(out)));
                        }
                    }
                } else {
                    self.pos += 1;
                }
            }
        }

        // Campo sin comillas
        let start = self.pos;
        while self.pos < len && bytes[self.pos] != b',' {
            self.pos += 1;
        }

        let field = &self.line[start..self.pos];

        if self.pos < len {
            self.pos += 1; // consumir coma
        } else {
            self.done = true;
        }

        Some(Ok(Cow::Borrowed(field)))
    }
}

