    action: Literal["status", "echo", "set_interval"]
    args: dict = {}

@app.post("/register")
def register(body: Register, _=Depends(auth)):
    agents[body.agent_id] = {
        **body.model_dump(),
        "last_seen": now(),
    }
    commands.setdefault(body.agent_id, [])
    return {"ok": True, "poll_interval": 10, "jitter": 5}

@app.post("/poll/{agent_id}")
def poll(agent_id: str, body: Poll = Poll(), _=Depends(auth)):
    if agent_id not in agents:
        raise HTTPException(status_code=404, detail="unknown agent")

    agents[agent_id]["last_seen"] = now()

    pending = commands.get(agent_id, [])
    batch = pending[:5]
    commands[agent_id] = pending[5:]

    return {"commands": batch, "server_time": now()}

