static std::wstring ReadDefaultString(HKEY root, const std::wstring& subkey) {
    HKEY hKey = nullptr;
    if (RegOpenKeyExW(root, subkey.c_str(), 0, KEY_READ, &hKey) != ERROR_SUCCESS) {
        return L"";
    }

    DWORD type = 0;
    DWORD bytes = 0;
    LONG st = RegQueryValueExW(hKey, nullptr, nullptr, &type, nullptr, &bytes);

    std::wstring value;
    if (st == ERROR_SUCCESS &&
        (type == REG_SZ || type == REG_EXPAND_SZ) &&
        bytes >= sizeof(wchar_t)) {

        std::vector<wchar_t> buf(bytes / sizeof(wchar_t) + 1, L'\0');
        if (RegQueryValueExW(hKey, nullptr, nullptr, &type,
                             reinterpret_cast<LPBYTE>(buf.data()), &bytes) == ERROR_SUCCESS) {
            value.assign(buf.data());
        }
    }

    RegCloseKey(hKey);
    return value;
}

