package wire

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"errors"
	"io"
)

// DefaultPSKHex is a development key (AES-256). Override with -psk on both ends.
const DefaultPSKHex = "9f2c4e7a1b8d3f605a7e2c4b9d1f8a3e6c5b2d4f7a9e1c3b5d7f9a2e4c6b8d10"

var ErrShortCiphertext = errors.New("wire: ciphertext too short")

// Envelope is the only thing that crosses the wire as JSON.
type Envelope struct {
	Blob string `json:"blob"`
}

// Seal encrypts plaintext under key, returns nonce||ciphertext base64'd.
func Seal(key, plaintext []byte) (*Envelope, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}
	ct := gcm.Seal(nil, nonce, plaintext, nil)
	out := make([]byte, 0, len(nonce)+len(ct))
	out = append(out, nonce...)
	out = append(out, ct...)
	return &Envelope{Blob: base64.StdEncoding.EncodeToString(out)}, nil
}

// Open reverses Seal.
func Open(key []byte, e *Envelope) ([]byte, error) {
	raw, err := base64.StdEncoding.DecodeString(e.Blob)
	if err != nil {
		return nil, err
	}
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	if len(raw) < gcm.NonceSize() {
		return nil, ErrShortCiphertext
	}
	n := gcm.NonceSize()
	return gcm.Open(nil, raw[:n], raw[n:], nil)
}

// Marshal seals a JSON-encoded value.
func Marshal(key []byte, v any) (*Envelope, error) {
	b, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	return Seal(key, b)
}

// Unmarshal opens an envelope and decodes JSON into v.
func Unmarshal(key []byte, e *Envelope, v any) error {
	b, err := Open(key, e)
	if err != nil {
		return err
	}
	return json.Unmarshal(b, v)
}

