//!
//! Memoria: O(1 MiB) de buffer + el registro más grande. Nunca carga el archivo completo.

use std::error::Error;
use std::fmt;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read};
use std::path::Path;

/// Buffer de lectura. 1 MiB reduce syscalls sin inflar el RSS.
const IO_BUF: usize = 1 << 20;

// ---------------------------------------------------------------------------
// Errores
