#[derive(Debug)]
pub enum CsvError {
    Io(io::Error),
    /// La columna existe pero no tenía ningún valor numérico.
    NoData,
    /// `mean_of_column_named` no encontró el nombre en el encabezado.
    ColumnNotFound(String),
    /// Un registro tiene menos campos que el índice pedido.
    ColumnMissing { record: u64, offset: u64, column: usize, present: usize },
    InvalidUtf8  { record: u64, offset: u64, column: usize },
    NotNumeric   { record: u64, offset: u64, column: usize, value: String },
    NonFinite    { record: u64, offset: u64, column: usize, value: String },
}

impl fmt::Display for CsvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CsvError::Io(e) => write!(f, "error de E/S: {e}"),
            CsvError::NoData => write!(f, "no hay valores numéricos en la columna"),
            CsvError::ColumnNotFound(n) => {
                write!(f, "no existe la columna «{n}» en el encabezado")
            }
            CsvError::ColumnMissing { record, offset, column, present } => write!(
                f,
                "registro {record} (byte {offset}): la columna {column} no existe, \
                 el registro solo tiene {present} campos"
            ),
            CsvError::InvalidUtf8 { record, offset, column } => write!(
                f,
                "registro {record} (byte {offset}): la columna {column} no es UTF-8 válido"
            ),
            CsvError::NotNumeric { record, offset, column, value } => write!(
                f,
                "registro {record} (byte {offset}): valor no numérico {value:?} \
                 en la columna {column}"
            ),
            CsvError::NonFinite { record, offset, column, value } => write!(
                f,
                "registro {record} (byte {offset}): valor no finito {value:?} \
                 en la columna {column}"
            ),
        }
    }
}

impl Error for CsvError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            CsvError::Io(e) => Some(e),
            _ => None,
        }
    }
}

impl From<io::Error> for CsvError {
    fn from(e: io::Error) -> Self {
        CsvError::Io(e)
    }
}

