```go
func Unicos[T, K comparable](in []T, clave func(T) K) []T {
	vistos := make(map[K]struct{}, len(in))
	out := make([]T, 0, len(in))
	for _, v := range in {
		k := clave(v)
		if _, ok := vistos[k]; ok {
			continue
		}
		vistos[k] = struct{}{}
		out = append(out, v)
	}
